17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.Collections;
22	import java.util.List;
23	import java.util.Map;
24	import java.util.Objects;
25	import java.util.stream.Collectors;
26	
27	import org.slf4j.Logger;
28	import org.slf4j.LoggerFactory;
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.security.core.Authentication;
33	import org.springframework.security.core.context.SecurityContextHolder;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /**
66	     * Dedicated audit logger recording every successful owner creation.
67	     */
68	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
119	        if (ownerAlreadyExists(owner) || emailAlreadyExists(owner)) {
120	            return new ResponseEntity<>(HttpStatus.CONFLICT);
121	        }
122	        if (dailyRegistrationLimitReached()) {
123	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
124	        }
125	        if (cityAtCapacity(owner.getCity())) {
126	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
127	        }
128	        if (owner.getRegistrationDate() == null) {
129	            owner.setRegistrationDate(LocalDate.now());
130	        }
131	        owner.setCity(resolveCity(owner.getCity()));
132	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
133	        owner.setMembershipNumber(membershipNumber);
134	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
135	        owner.setMembershipTier(membershipTierFor(membershipNumber));
136	        owner.setNamesakeCount(namesakeCount(owner.getLastName()));
137	        owner.setSharesHousehold(sharesHousehold(owner));
138	        owner.setLocality(localityFor(owner.getCity()));
139	        this.clinicService.saveOwner(owner);
140	        AUDIT.info("owner created: user={} ownerId={} membershipNumber={}",
141	            currentUsername(), owner.getId(), owner.getMembershipNumber());
142	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
143	        headers.setLocation(UriComponentsBuilder.newInstance()
144	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
145	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
146	    }
147	
148	    /**
149	     * Resolves the name of the currently authenticated user for audit logging, falling back to
150	     * {@code "anonymous"} when no authentication is present in the security context.
151	     *
152	     * @return the authenticated user's name, or {@code "anonymous"} if unauthenticated
153	     */
154	    private static String currentUsername() {
155	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
156	        return authentication != null ? authentication.getName() : "anonymous";
157	    }
158	
159	    /**
160	     * The maximum number of owners that may be registered on any single day (by registration date).
161	     */
162	    private static final long MAX_OWNERS_PER_DAY = 20;
163	
164	    /**
165	     * Determines whether the maximum number of owners for the current day has already been reached.
166	     * Owners are counted by their registration date, so once {@value #MAX_OWNERS_PER_DAY} owners
167	     * carry today's registration date no further owners may be created today.
168	     *
169	     * @return {@code true} if today's registration limit has been reached
170	     */
171	    private boolean dailyRegistrationLimitReached() {
172	        LocalDate today = LocalDate.now();
173	        long registeredToday = this.clinicService.findAllOwners().stream()
174	            .filter(existing -> today.equals(existing.getRegistrationDate()))
175	            .count();
176	        return registeredToday >= MAX_OWNERS_PER_DAY;
177	    }
178	
179	    /**
180	     * The maximum number of owners that may be registered in any single city.
181	     */
182	    private static final long MAX_OWNERS_PER_CITY = 8;
183	
184	    /**
185	     * Determines whether the given city has already reached its capacity of
186	     * {@value #MAX_OWNERS_PER_CITY} owners. Owners are counted per city ignoring letter case, so
187	     * once a city holds {@value #MAX_OWNERS_PER_CITY} owners no further owners may be created there.
188	     *
189	     * @param city the raw city supplied for the owner being created, may be {@code null}
190	     * @return {@code true} if the city already contains the maximum number of owners
191	     */
192	    private boolean cityAtCapacity(String city) {
193	        if (city == null) {
194	            return false;
195	        }
196	        long ownersInCity = this.clinicService.findAllOwners().stream()
197	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
198	            .count();
199	        return ownersInCity >= MAX_OWNERS_PER_CITY;
200	    }
201	
202	    /**
203	     * Resolves the city to store for a newly created owner. If another owner is already stored in
204	     * the same city (compared ignoring letter case), that existing owner's exact spelling of the
205	     * city name is reused so that a single city is always represented consistently. Otherwise the
206	     * supplied city is title-cased (see {@link #titleCase(String)}) before being stored.
207	     *
208	     * @param city the raw city supplied for the owner being created, may be {@code null}
209	     * @return the city to store, or {@code null} if {@code city} is {@code null}
210	     */
211	    private String resolveCity(String city) {
212	        if (city == null) {
213	            return null;
214	        }
215	        return this.clinicService.findAllOwners().stream()
216	            .map(Owner::getCity)
217	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
218	            .findFirst()
219	            .orElseGet(() -> titleCase(city));
220	    }
221	
222	    /**
223	     * Title-cases a value so that the first letter of every whitespace-separated word is
224	     * upper-cased and every other letter is lower-cased, preserving the original whitespace. For
225	     * example {@code "new  york"} becomes {@code "New  York"} and {@code "LONDON"} becomes
226	     * {@code "London"}.
227	     *
228	     * @param value the raw value, may be {@code null}
229	     * @return the title-cased value, or {@code null} if {@code value} is {@code null}
230	     */
231	    private static String titleCase(String value) {
232	        if (value == null) {
233	            return null;
234	        }
235	        StringBuilder result = new StringBuilder(value.length());
236	        boolean startOfWord = true;
237	        for (int i = 0; i < value.length(); i++) {
238	            char c = value.charAt(i);
239	            if (Character.isWhitespace(c)) {
240	                startOfWord = true;
241	                result.append(c);
242	            } else {
243	                result.append(startOfWord ? Character.toUpperCase(c) : Character.toLowerCase(c));
244	                startOfWord = false;
245	            }
246	        }
247	        return result.toString();
248	    }
249	
250	    /**
251	     * Builds the customer code for a newly created owner in the given city, formatted as
252	     * {@code <UPPERCASE_CITY>-<NNNN>} where {@code NNNN} is one more than the number of owners
253	     * already stored in that city, zero-padded to four digits (e.g. {@code LONDON-0007}). The
254	     * count of existing owners in the city ignores letter case.
255	     *
256	     * @param city the city of the owner being created
257	     * @return the assigned customer code
258	     */
259	    private String nextCustomerCode(String city) {
260	        long ownersInCity = this.clinicService.findAllOwners().stream()
261	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
262	            .count();
263	        return String.format("%s-%04d", city.toUpperCase(), ownersInCity + 1);
264	    }
265	
266	    /**
267	     * The maximum membership number that still qualifies an owner for the founding tier. The
268	     * first {@value #MAX_FOUNDING_MEMBERS} owners ever created are founding members.
269	     */
270	    private static final int MAX_FOUNDING_MEMBERS = 100;
271	
272	    /**
273	     * Resolves the membership tier for a newly created owner from its sequential membership
274	     * number. The first {@value #MAX_FOUNDING_MEMBERS} owners ever created are {@code FOUNDING};
275	     * every later owner is {@code STANDARD}.
276	     *
277	     * @param membershipNumber the owner's sequential membership number
278	     * @return {@code "FOUNDING"} or {@code "STANDARD"}
279	     */
280	    private static String membershipTierFor(int membershipNumber) {
281	        return membershipNumber <= MAX_FOUNDING_MEMBERS ? "FOUNDING" : "STANDARD";
282	    }
283	
284	    /**
285	     * Counts how many existing owners already share the given last name, ignoring letter case and
286	     * surrounding or repeated whitespace. This is evaluated at the moment a new owner is created,
287	     * before that owner is stored, so it reflects the number of other owners that carry the same
288	     * last name.
289	     *
290	     * @param lastName the last name of the owner being created, may be {@code null}
291	     * @return the number of other owners already sharing that last name
292	     */
293	    private int namesakeCount(String lastName) {
294	        String normalized = normalize(lastName);
295	        return (int) this.clinicService.findAllOwners().stream()
296	            .filter(existing -> Objects.equals(normalize(existing.getLastName()), normalized))
297	            .count();
298	    }
299	
300	    /**
301	     * Determines whether another owner already shares a household with the owner being created,
302	     * meaning an existing owner already has the same address and city. Both address and city are
303	     * compared ignoring letter case and surrounding or repeated whitespace (see
304	     * {@link #normalize(String)}). This is evaluated before the new owner is stored, so it reflects
305	     * only owners that already existed.
306	     *
307	     * @param owner the candidate owner to check
308	     * @return {@code true} if a stored owner already has the same address and city
309	     */
310	    private boolean sharesHousehold(Owner owner) {
311	        String address = normalize(owner.getAddress());
312	        String city = normalize(owner.getCity());
313	        return this.clinicService.findAllOwners().stream()
314	            .anyMatch(existing -> Objects.equals(normalize(existing.getAddress()), address)
315	                && Objects.equals(normalize(existing.getCity()), city));
316	    }
317	
318	    /**
319	     * The locality assigned to an owner whose city is the single most common city among the
320	     * existing owners at the moment of creation.
321	     */
322	    private static final String LOCALITY_LOCAL = "local";
323	
324	    /**
325	     * The locality assigned to an owner whose city is not the single most common city among the
326	     * existing owners at the moment of creation.
327	     */
328	    private static final String LOCALITY_REMOTE = "remote";
329	
330	    /**
331	     * Resolves the locality for a newly created owner. The owner is {@code "local"} when their city
332	     * is the single most common city among the owners that already exist (compared ignoring letter
333	     * case and surrounding or repeated whitespace, see {@link #normalize(String)}); otherwise they
334	     * are {@code "remote"}. If there is no existing owner, or the most common city is shared by a
335	     * tie, or the owner's city is not that single most common city, the owner is {@code "remote"}.
336	     * This is evaluated before the new owner is stored, so it reflects only owners that already
337	     * existed.
338	     *
339	     * @param city the city of the owner being created, may be {@code null}
340	     * @return {@code "local"} or {@code "remote"}
341	     */
342	    private String localityFor(String city) {
343	        if (city == null) {
344	            return LOCALITY_REMOTE;
345	        }
346	        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
347	            .map(Owner::getCity)
348	            .filter(Objects::nonNull)
349	            .collect(Collectors.groupingBy(OwnerRestControllerV1::normalize, Collectors.counting()));
350	        if (countsByCity.isEmpty()) {
351	            return LOCALITY_REMOTE;
352	        }
353	        long max = Collections.max(countsByCity.values());
354	        List<String> mostCommon = countsByCity.entrySet().stream()
355	            .filter(entry -> entry.getValue() == max)
356	            .map(Map.Entry::getKey)
357	            .toList();
358	        if (mostCommon.size() != 1) {
359	            return LOCALITY_REMOTE;
360	        }
361	        return mostCommon.get(0).equals(normalize(city)) ? LOCALITY_LOCAL : LOCALITY_REMOTE;
362	    }
363	
364	    /**
365	     * Determines whether an owner already exists using the same telephone number.
366	     * Comparison ignores letter case and surrounding or repeated whitespace.
367	     *
368	     * @param owner the candidate owner to check
369	     * @return {@code true} if any other owner with the same telephone is already stored
370	     */
371	    private boolean ownerAlreadyExists(Owner owner) {
372	        String telephone = normalizeTelephone(owner.getTelephone());
373	        return this.clinicService.findAllOwners().stream()
374	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
375	    }
376	
377	    /**
378	     * Normalizes a telephone number to digits only, stripping spaces, dashes and
379	     * parentheses (any non-digit character). This is the canonical stored form and is
380	     * used for the telephone-uniqueness check, so {@code "(613) 555-0100"} and
381	     * {@code "6135550100"} are treated as the same number.
382	     *
383	     * @param telephone the raw telephone value, may be {@code null}
384	     * @return the digits-only value, or {@code null} if {@code telephone} is {@code null}
385	     */
386	    private static String normalizeTelephone(String telephone) {
387	        if (telephone == null) {
388	            return null;
389	        }
390	        return telephone.replaceAll("[^0-9]", "");
391	    }
392	
393	    /**
394	     * Determines whether another owner already uses the same email address.
395	     * Owners without an email are ignored, so a missing email never conflicts.
396	     * Comparison ignores letter case and surrounding or repeated whitespace.
397	     *
398	     * @param owner the candidate owner to check
399	     * @return {@code true} if the candidate supplies an email already used by a stored owner
400	     */
401	    private boolean emailAlreadyExists(Owner owner) {
402	        String email = normalize(owner.getEmail());
403	        if (email == null || email.isEmpty()) {
404	            return false;
405	        }
406	        return this.clinicService.findAllOwners().stream()
407	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
408	    }
409	
410	    /**
411	     * Normalizes a value for duplicate detection so that comparisons ignore letter
412	     * case and surrounding or repeated whitespace. Leading and trailing whitespace is
413	     * trimmed, any run of internal whitespace is collapsed to a single space, and the
414	     * result is lower-cased. For example {@code "  john   smith "} and {@code "John Smith"}
415	     * both normalize to {@code "john smith"}.
416	     *
417	     * @param value the raw value, may be {@code null}
418	     * @return the normalized value, or {@code null} if {@code value} is {@code null}
419	     */
420	    private static String normalize(String value) {
421	        if (value == null) {
422	            return null;
423	        }
424	        return value.strip().replaceAll("\\s+", " ").toLowerCase();
425	    }
426	
427	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
428	    @Override
429	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
430	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
431	        if (currentOwner == null) {
432	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
433	        }
434	        currentOwner.setAddress(ownerFieldsDto.getAddress());
435	        currentOwner.setCity(ownerFieldsDto.getCity());
436	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
437	        currentOwner.setLastName(ownerFieldsDto.getLastName());
438	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
439	        this.clinicService.saveOwner(currentOwner);
440	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
441	    }
442	
443	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
444	    @Transactional
445	    @Override
446	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
447	        Owner owner = this.clinicService.findOwnerById(ownerId);
448	        if (owner == null) {
449	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
450	        }
451	        this.clinicService.deleteOwner(owner);
452	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
453	    }
454	
455	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
456	    @Override
457	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
458	        Owner owner = this.clinicService.findOwnerById(ownerId);
459	        if (owner == null) {
460	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
461	        }
462	        HttpHeaders headers = new HttpHeaders();
463	        Pet pet = petMapper.toPet(petFieldsDto);
464	        owner.setId(ownerId);
465	        pet.setOwner(owner);
466	        pet.getType().setName(null);
467	        this.clinicService.savePet(pet);
468	        PetDto petDto = petMapper.toPetDto(pet);
469	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
470	            .buildAndExpand(pet.getId()).toUri());
471	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
472	    }
473	
474	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
475	    @Override
476	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
477	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
478	        if (currentOwner != null) {
479	            Pet currentPet = this.clinicService.findPetById(petId);
480	            if (currentPet != null) {
481	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
482	                currentPet.setName(petFieldsDto.getName());
483	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
484	                this.clinicService.savePet(currentPet);
485	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
486	            }
487	        }
488	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
489	    }
490	
491	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
492	    @Override
493	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
494	        HttpHeaders headers = new HttpHeaders();
495	        Visit visit = visitMapper.toVisit(visitFieldsDto);
496	        Pet pet = new Pet();
497	        pet.setId(petId);
498	        visit.setPet(pet);
499	        this.clinicService.saveVisit(visit);
500	        VisitDto visitDto = visitMapper.toVisitDto(visit);
501	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
502	            .buildAndExpand(visit.getId()).toUri());
503	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
504	    }
505	
506	
507	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
508	    @Override
509	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
510	        Owner owner = this.clinicService.findOwnerById(ownerId);
511	        if (owner != null) {
512	            Pet pet = owner.getPet(petId);
513	            if (pet != null) {
514	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
515	            }
516	        }
517	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
518	    }
519	}
